        w(14, .mitbestimmung, "Viele Mitarbeiter der CBA-IT-Service GmbH sind Mitglied einer Gewerkschaft.\nWelche der folgenden Aussagen über gewerkschaftliche Aufgaben und Forderungen trifft zu?",
          ["Die Gewerkschaften verhandeln u. a. mit Arbeitgeberverbänden über die Verbesserung von Arbeitsbedingungen.", "Das Grundgesetz räumt den Gewerkschaften lediglich ein Recht für den Abschluss von Lohntarifverträgen ein.", "Gewerkschaftsvertreter dürfen zu Betriebsversammlungen nicht eingeladen werden.", "Die Gewerkschaften dürfen sich nicht für eine Humanisierung der Arbeitsbedingungen einsetzen.", "Die Gewerkschaften dürfen ihren Mitgliedern keinen Rechtsschutz in arbeitsgerichtlichen Rechtsstreitigkeiten gewähren."],
          "Gewerkschaften handeln als Tarifpartner Arbeitsbedingungen aus."),
        w(15, .unternehmen, "Die CBA-IT-Service GmbH wird in der Rechtsform einer GmbH geführt.\nWelche der folgenden Aussagen trifft auf die Rechtsform der GmbH zu?",
          ["Die Gesellschafter der GmbH haften nur mit ihrer Stammeinlage.", "Die GmbH erzielt immer die beste Eigenkapitalrentabilität.", "Die GmbH gehört zu den Personengesellschaften.", "Die Gesellschafter dürfen nicht gleichzeitig Geschäftsführer sein.", "Das Stammkapital muss mindestens 50.000 EUR betragen."],
          "Bei der GmbH ist die Haftung auf das Gesellschaftsvermögen bzw. die Einlage beschränkt. (Das Mindeststammkapital beträgt 25.000 EUR.)"),
        w(16, .unternehmen, "Die CBA-IT-Service GmbH erzielte im vergangenen Geschäftsjahr einen Reingewinn von 24.860,00 EUR. Das Eigenkapital betrug 220.000,00 EUR.\nBerechnen Sie die Eigenkapitalrentabilität.",
